function [x,N,res] = pfix(f,x0,tol,MaxIt,Dxmin,Dxmax)% Looks for a point F such that func(F)=F% Iteration ends either when the error, defined% as the distance between two successive iterates is less than tol, or when% the number of  iterations exceeds the maximum allowed value MaxIt, or when% the iteration goes outside either the interval [x0 - Dxmin, x0 + Dxmax]% or the natural real domain of func.%% This function also produces a picture showing the evolution of the error.%% OUTPUTS:% x = the solution% N = the number of iterations% res = the final error%% DEFAULTS:% tol   = 2*eps*abs(x0)% MaxIt = 10000% Dxmin = 2^52*abs(x0)% Dxmax = 2^52*abs(x0)% %% EXAMPLES TO TRY:% >> [x,N,res] = pfix(@(x) x,3)% >> [x,N,res] = pfix(@(x) -0.3*log(x),0.78193,1e-4,100,realmax,realmax)% >> [x,N,res] = pfix(@(x) -0.2*log(x),0.3)% >> [x,N,res] = pfix(@(x) 3 - exp(0.4*x),1,1e-5,100,2,2)%En MATLAB, un argumento se considera opcional principalmente por cmo est% estructurado el cdigo de la funcin para manejar la ausencia de dicho % argumento. A diferencia de algunos otros lenguajes de programacin que % tienen una sintaxis especfica para definir argumentos opcionales % directamente en la firma de la funcin, MATLAB requiere que el desarrollador% implemente manualmente la lgica para gestionar los argumentos opcionales.% Matlab utiliza la funcin nargin para verificar cuntos argumentos de entrada% se han pasado a una funcin. Si el nmero de argumentos pasados es menor % que el nmero total de argumentos definidos, los argumentos faltantes se % consideran opcionales, y la funcin debe contener una lgica para asignar% valores predeterminados a estos argumentos opcionales o para manejar su % ausencia de alguna otra manera.% Inicializacin y Verificacin: Se establecen valores predeterminados para% tol, MaxIt, Dxmin, y Dxmax si no se proporcionan, y se verifica que se% hayan dado los argumentos necesarios.if nargin < 2    error('A function handle and a starting point are needed')endif nargin<3    if x0 ~= 0        tol = 8*eps*abs(x0);    else        tol = 16*eps;    endendif nargin<4    MaxIt = 1000;endif x0 ~= 0 && nargin<5      Dxmin = 2^52*abs(x0);elseif nargin<5	Dxmin = -2^52*tol;endif x0 ~= 0 && nargin<6      Dxmax = min(Dxmin,2^52*abs(x0));elseif nargin<6	Dxmax = 2^52*tol;endx    = x0;N    = 0;res(1) = abs(x-f(x));if res(1)==0; warning('Point is a fixed point'); return; end;figure(1)subplot(1,2,1)hold onwhile (res(end)>tol) && (N < MaxIt)     N = N+1;    fx = f(x);     if (imag(fx) ~= 0) || (~isfinite(fx))        warning('Iteration reached the outside of the domain of f after %d iterations', N)        break    end        % Dibujamos segmentos rojos en un grfico para ilustrar la aproximacin de    % punto fijo.    plot([x, x], [x, fx],'r--');    plot([x, fx], [fx, fx],'r--');    res(N+1) = abs(fx - x);    x = fx;    disp(x)endif N < 2    close(1)    warning('No figure will be displayed since only one iteration has been performed')    returnendif (x > x0+Dxmax) || (x < x0-Dxmin)    warning('Iteration reached the outside of the allowed search region after %d iterations', N)elseif N >= MaxIt    warning('Maximum number %d of iterations reached', N)endR = res(N);fplot(f)fplot(@(x) x,'g')axis tighttitle('Fixed point iteration')subplot(1,2,2)plot(res(2:N), 'r-o','DisplayName','Error')title('Error vs. Iteraciones')xlabel('Nmero de Iteraciones')hold onplot(log(res(2:N)), 'b-o','DisplayName','log(Error)')grid onlegend showaxis tightend